sp_widget.css:
.sp-tagline-color {
  color: $sp-tagline-color;
}

@media (forced-colors: active) {
  .sp-search-heading {
    background-color: Canvas;
  }
}

#homepage-search {
  /* Search heading — gradient text matching SPAR brand */
  .sp-search-heading {
    background: linear-gradient(135deg, $brand-primary 0%, $brand-success 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    font-family: "Libre Baskerville", serif;
    font-weight: 700;
    letter-spacing: -0.02em;
  }

  /* Search container */
  .aisearch {
    --classicsponlydonotuse--rem-multipy: 1.6;
  }

  .aisearch-container {
    height: 36px;
    border-radius: 999px !important;
    border: 1px solid #E0E0E0 !important;
    background: $glass-bg !important;
    backdrop-filter: blur(8px) !important;
    transition: border-color 250ms ease, box-shadow 250ms ease !important;
    overflow: hidden;
  }

  .aisearch-container:focus-within {
    border-color: transparent !important;
    box-shadow: 0 0 0 3px rgba(227, 6, 19, 0.15),
                0 6px 20px rgba(0, 0, 0, 0.08) !important;
    background: #ffffff !important;
  }

  /* Search input inside container */
  .aisearch-container input,
  .aisearch-container input[type="search"],
  .aisearch-container input[type="text"] {
    border: none !important;
    background: transparent !important;
    font-family: "Libre Baskerville", serif !important;
    color: #1D272B !important;
    padding-left: 16px !important;
  }

  .aisearch-container input::placeholder {
    color: $text-muted !important;
  }

  /* Search icon — green to match brand */
  .aisearch-container .fa-search,
  .aisearch-container [class*="search-icon"] {
    color: $brand-success !important;
    transition: color 250ms ease, transform 250ms ease !important;
  }

  .aisearch-container:focus-within .fa-search,
  .aisearch-container:focus-within [class*="search-icon"] {
    color: $brand-primary !important;
    transform: scale(1.15) !important;
  }
}

/* On smaller screens, reduce padding, font-size */
@media (max-width: 767px) {
  .wrapper-xl {
    padding: 10px !important;
  }

  .sp-search-heading {
    font-size: 30px;
    word-break: break-word;
    -webkit-text-fill-color: #E30613;
  }

  #homepage-search .aisearch-container {
    height: 44px !important;
  }
}

sp_widget.link:
function link() {
      var geckoRegex = /Gecko\/\d+/; // Remove forced-colors css for Gecko engine (Firefox) as they already handle it
      if (geckoRegex.test(navigator.userAgent)) {
        $('.sp-search-heading').removeClass('sp-search-heading');
      }
}

sp_widget.script:
var aisEnabled = $sp.isAISearchEnabled();

if (aisEnabled) {
    options['utterancePlacement'] = 'body';
    options['placement'] = 'dynamic-landing';
	data.typeAheadSearch = $sp.getWidget('typeahead-search', options);
} else
	data.typeAheadSearch = $sp.getWidget('typeahead-search', options.typeahead_search);
